SELECT 100.0 * SUM(CASE WHEN p.height < 180 AND la.overall_rating > 70 THEN 1 ELSE 0 END) / COUNT(p.id) AS percentage
FROM Player p
LEFT JOIN (
  SELECT pa.player_api_id, pa.overall_rating
  FROM Player_Attributes pa
  WHERE pa.date = (
    SELECT MAX(pa2.date) FROM Player_Attributes pa2 WHERE pa2.player_api_id = pa.player_api_id
  )
) la ON p.player_api_id = la.player_api_id;

WITH plus AS (
  SELECT molecule_id FROM molecule WHERE label = '+'
), f_mols AS (
  SELECT DISTINCT molecule_id FROM atom WHERE element = 'f' AND molecule_id IN (SELECT molecule_id FROM plus)
)
SELECT CASE WHEN (SELECT COUNT(*) FROM plus)=0 THEN 0.0
            ELSE (((SELECT COUNT(*) FROM plus) - (SELECT COUNT(*) FROM f_mols)) * 100.0) / (SELECT COUNT(*) FROM plus)
       END AS percentage_no_f;

